// vine along a parametric path
const vine=(fn,n,name)=>{
  const P=[];for(let i=0;i<=n*8;i++)P.push(fn(i/(n*8)));
  const d='M'+P.map(p=>p[0].toFixed(1)+' '+p[1].toFixed(1)).join('L');
  let out=`<path class="stem" d="${d}" fill="none" stroke="${INK}" stroke-width="11" stroke-linecap="round"/><path class="stem" d="${d}" fill="none" stroke="${GR}" stroke-width="6" stroke-linecap="round"/>`;
  for(let i=1;i<n;i++){
    const k=i*8,p=P[k],q=P[k+1],ang=Math.atan2(q[1]-p[1],q[0]-p[0])*180/Math.PI;
    const side=i%2?1:-1;
    out+=leaf(p[0],p[1],ang+side*55,1.1,leafCols[i%4]);
    out+=leaf(p[0],p[1],ang-side*70,.75,leafCols[(i+2)%4]);
    // tendril with gold ball
    const ta=(ang-side*95)*Math.PI/180,L=46,ex=p[0]+Math.cos(ta)*L,ey=p[1]+Math.sin(ta)*L;
    out+=`<path d="M${p[0].toFixed(1)} ${p[1].toFixed(1)}Q${(p[0]+Math.cos(ta)*L*.3+Math.cos(ta+1.57*side)*22).toFixed(1)} ${(p[1]+Math.sin(ta)*L*.3+Math.sin(ta+1.57*side)*22).toFixed(1)} ${ex.toFixed(1)} ${ey.toFixed(1)}" fill="none" stroke="${INK}" stroke-width="3"/>`+ball(ex,ey,13);
  }
  return out;
};
